5	/**
6	 * Shared owner identity for the create-owner pipeline: derives the single canonical
7	 * {@code identityKey} that consolidates all duplicate detection.
8	 *
9	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
10	 * with telephone canonicalized to E.164 (see {@link OwnerTelephones}) and email lower-cased
11	 * (see {@link OwnerEmails}); a missing component contributes an empty string. Two owners are
12	 * duplicates exactly when their whole keys are equal — so members of the same household
13	 * (same {@code householdId}) with different telephones have different keys and are both
14	 * allowed.
15	 */
16	public final class OwnerIdentities {
17	
18	    private OwnerIdentities() {
19	    }
20	
21	    /**
22	     * Canonical identity key for the given components. {@code telephone} is normalized to
23	     * E.164 and {@code email} lower-cased before assembly; any {@code null} component
24	     * contributes an empty string.
25	     */
26	    public static String key(String telephone, String email, String householdId) {
27	        return part(OwnerTelephones.toE164(telephone)) + "|" + part(OwnerEmails.normalize(email))
28	                + "|" + part(householdId);
29	    }
30	
31	    /** Canonical {@link #key(String, String, String)} for an existing owner's stored fields. */
32	    public static String of(Owner owner) {
33	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
34	    }
35	
36	    private static String part(String value) {
37	        return value == null ? "" : value;
38	    }
39	}
