18	/**
19	 * Derives an owner's numeric membership level from the owner's own fields.
20	 *
21	 * <p>The level starts at {@value #MIN}; a present email adds one; having no
22	 * namesakes (namesakeCount is 0) adds one; the total is capped at {@value #MAX}.
23	 * Level 4 is reserved for tenure and is not awarded here.
24	 */
25	public final class MembershipLevel {
26	
27	    /** The level every owner starts at. */
28	    public static final int MIN = 1;
29	
30	    /** The highest level derivable from an owner's own fields; level 4 is reserved for tenure. */
31	    public static final int MAX = 3;
32	
33	    private MembershipLevel() {
34	    }
35	
36	    /**
37	     * Derive the membership level for the given owner.
38	     *
39	     * @param owner the owner (must not be {@code null}).
40	     * @return the level, from {@value #MIN} to {@value #MAX}.
41	     */
42	    public static int of(Owner owner) {
43	        int level = MIN;
44	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
45	            level++;
46	        }
47	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
48	            level++;
49	        }
50	        return Math.min(level, MAX);
51	    }
52	}
