1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The single duplicate check for create-owner: rejects a request whose derived
11	 * {@code identityKey} exactly equals an existing owner's, responding 409 via
12	 * {@link DuplicateOwnerException}. Consolidates the former separate telephone, email and
13	 * household checks into one {@link OwnerIdentities key}.
14	 *
15	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the
16	 * request telephone is already E.164 and its email lower-cased. The household component
17	 * matches {@link AssignOwnerHousehold}: an owner opting in with {@code sharesHousehold}
18	 * gets the shared {@code householdId}, otherwise it is absent.
19	 */
20	public class RequireUniqueIdentity {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateOwnerException {
24	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
25	                ? OwnerHouseholds.id(request.getLastName(), request.getAddress())
26	                : null;
27	        String identityKey = OwnerIdentities.key(request.getTelephone(), request.getEmail(), householdId);
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (identityKey.equals(OwnerIdentities.of(existing))) {
30	                throw new DuplicateOwnerException(identityKey);
31	            }
32	        }
33	    }
34	}
