1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.PostcodeRange;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
7	
8	/**
9	 * Rejects a create-owner request whose supplied postcode is malformed (not exactly four digits)
10	 * or out of range for the owner's city region, responding 400 via {@link InvalidPostcodeException}.
11	 * Postcode is validated only WHEN PRESENT: an absent postcode is accepted, keeping the request
12	 * contract backward-compatible. Region membership is checked against the pinned
13	 * {@link PostcodeRange} table; a city with no known region accepts any 4-digit postcode.
14	 */
15	public class RequirePostcodeInRegion {
16	
17	    private static final String FOUR_DIGITS = "[0-9]{4}";
18	
19	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
20	        String postcode = request.getPostcode();
21	        if (postcode == null) {
22	            return;
23	        }
24	        if (!postcode.matches(FOUR_DIGITS)
25	                || !PostcodeRange.isValidForCity(request.getCity(), postcode)) {
26	            throw new InvalidPostcodeException(request.getCity(), postcode);
27	        }
28	    }
29	}
