36	    /** The owner's derived duplicate-detection key - see {@link OwnerIdentities}. */
37	    default String identityKey(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        return OwnerIdentities.of(owner);
42	    }
43	
44	    /** The owner's preferred contact channel - 'EMAIL' when an email is present, otherwise 'PHONE'. */
45	    default String contactPreference(Owner owner) {
46	        if (owner == null) {
47	            return null;
48	        }
49	        return ContactPreference.forOwner(owner).name();
50	    }
51	
52	    /** The canonical region derived from the owner, preferring the postcode's region range and
53	     * falling back to the fixed city-to-region table, or 'UNKNOWN' when neither is known. */
54	    default String locality(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        return Locality.forCityAndPostcode(owner.getCity(), owner.getPostcode());
59	    }
60	
61	    /** Format the stored names as 'LastName, FirstName'. */
62	    default String displayName(Owner owner) {
63	        if (owner == null) {
64	            return null;
65	        }
66	        return owner.getLastName() + ", " + owner.getFirstName();
67	    }
68	
69	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
70	    default String initials(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        return initial(owner.getFirstName()) + initial(owner.getLastName());
75	    }
76	
77	    private static String initial(String name) {
78	        if (name == null || name.isEmpty()) {
79	            return "";
80	        }
81	        return Character.toUpperCase(name.charAt(0)) + ".";
82	    }
83	
84	    /**
