1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When a create-owner request opts in with {@code sharesHousehold} true, assigns the new
10	 * owner and every existing owner in the same household — same last name and address once
11	 * normalized (see {@link OwnerHouseholds}) — the same stable {@code householdId}. A no-op
12	 * for a request that does not opt in.
13	 *
14	 * <p>Runs after {@link BuildOwner}, so it works with the built {@link Owner} entity. The
15	 * {@code householdId} it assigns matches the household component of the {@code identityKey}
16	 * used by {@link RequireUniqueIdentity}.
17	 */
18	public class AssignOwnerHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
21	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String key = OwnerHouseholds.key(owner.getLastName(), owner.getAddress());
25	        String householdId = OwnerHouseholds.id(owner.getLastName(), owner.getAddress());
26	        owner.setHouseholdId(householdId);
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (key.equals(OwnerHouseholds.key(existing.getLastName(), existing.getAddress()))) {
29	                existing.setHouseholdId(householdId);
30	                ownerRepository.save(existing);
31	            }
32	        }
33	    }
34	}
